import gr.hua.dit.oop2.calendar.TimeService;
import gr.hua.dit.oop2.calendar.TimeTeller;
import java.util.Scanner;
import java.time.LocalDateTime;
import java.util.List;
import java.util.ArrayList;

import java.util.InputMismatchException;

public class Main {
    public static void main(String[] args) {

        try {
            if (args.length == 1) {
                String filename = args[0];
                GeneralFunctions.isIcsFile(filename);
                GeneralFunctions.printString("Welcome to the Calendar Manager!");
                CalendarManager calendar = new CalendarManager(filename);
                // Start a new thread that will continuously check for events that are within the next 24 hours
                Thread reminderThread = new Thread(() -> {
                    while (!Thread.currentThread().isInterrupted()) {
                        // Get all events from the calendar
                        List<Event> allEvents = calendar.getAllEvents();

                        // Create a list to store events that need reminders
                        List<Event> eventsWithReminders = new ArrayList<>();

                        // Iterate over all events
                        for (Event event : allEvents) {
                            // Check if the thread has been interrupted
                            if (Thread.currentThread().isInterrupted()) {
                                return;
                            }

                            // Check if the event is within the next 24 hours and after now
                            if (event.getEndDate().isBefore(LocalDateTime.now().plusHours(24))) {
                                // Add the event to the list of events that need reminders
                                eventsWithReminders.add(event);
                            }
                        }

                        // Iterate over the events that need reminders
                        for (Event event : eventsWithReminders) {
                            // Check if the thread has been interrupted
                            if (Thread.currentThread().isInterrupted()) {
                                return;
                            }

                            // Create a reminder for the event and start it
                            Reminder reminder = new Reminder(event);
                            reminder.start();
                        }

                        // Sleep the thread for 1 minute before checking again
                        try {
                            Thread.sleep(100);
                        } catch (InterruptedException e) {
                            Thread.currentThread().interrupt();
                        }
                    }
                });

                reminderThread.start();
                boolean x = true;
                while (x) {
                    GeneralFunctions.printString("Select an option:");
                    GeneralFunctions.printString("1. Add an Event");
                    GeneralFunctions.printString("2. Exit");
                    Scanner scanner = new Scanner(System.in);
                    int option = GeneralFunctions.checkIntegerInput(scanner, 1, 2, "beetween 1-2");
                    if (option == 0) { //To catch the error in the input
                        GeneralFunctions.printString("Invalid input. Please enter a valid number (1-2).");
                        continue;
                    }
                    UserConsoleInterface userInterface = new UserConsoleInterface(calendar);

                    switch (option) {
                        case 1:
                            userInterface.addEvent();
                            break;
                        case 2:
                            // Stop the reminder thread
                            reminderThread.interrupt();
                            x = false;
                            break;
                        default:
                            GeneralFunctions.printString("Invalid input. Please enter a valid option (1-2).");
                    }
                }
            } else {
                GeneralFunctions.printString("Invalid number of arguments. Usage: java -jar calendar.jar [command] filename");
            }
        } catch (Exception e) {
            GeneralFunctions.printString("Something went wrong.\n" + e.getMessage());
        }
    }

    // Runtime.getRuntime().addShutdownHook(new Thread(reminderThread::interrupt));
}

