    FILE* f = fopen(filename, "rb");
    MD5_CTX md5;
    MD5_Init(&md5);
    char buffer[1024];
    int bytes_read;
    while ((bytes_read = fread(buffer, 1, 1024, f)) > 0) {
        MD5_Update(&md5, buffer, bytes_read); 
